import { html } from '../lib/html.mjs';
import { icon } from './icons.mjs';

/** First line of every generated file. build.mjs uses it to recognise (and tidy up) its own output. */
export const GENERATED_MARKER = 'Generated by build.mjs';

const DEFAULT_SHARE_IMAGE = 'assets/img/hero-wide-1920.webp';

/** Link that opens a WhatsApp chat with the store, or '' when no number is set. */
export const whatsappUrl = (site) => (site.contact.whatsapp ? `https://wa.me/${site.contact.whatsapp}` : '');

function head(page, { site, assetVersion }) {
  const canonical = site.url ? `${site.url}/${page.file === 'index.html' ? '' : page.file}` : '';
  const shareImage = site.url ? `${site.url}/${page.image ?? DEFAULT_SHARE_IMAGE}` : '';

  return html`<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
${page.headStart ?? ''}
<title>${page.title}</title>
<meta name="description" content="${page.description}">
${page.noindex ? html`<meta name="robots" content="noindex">` : ''}
${canonical && !page.noindex ? html`<link rel="canonical" href="${canonical}">` : ''}
<meta name="theme-color" content="#0B0B0B">
<meta name="color-scheme" content="dark">
<meta property="og:site_name" content="${site.name}">
<meta property="og:type" content="${page.ogType ?? 'website'}">
<meta property="og:title" content="${page.shareTitle ?? page.title}">
<meta property="og:description" content="${page.description}">
${canonical ? html`<meta property="og:url" content="${canonical}">` : ''}
${shareImage ? html`<meta property="og:image" content="${shareImage}">
<meta name="twitter:card" content="summary_large_image">` : ''}
<link rel="icon" href="assets/img/favicon.svg" type="image/svg+xml">
<link rel="icon" href="assets/img/favicon.png" type="image/png" sizes="48x48">
<link rel="apple-touch-icon" href="assets/img/apple-touch-icon.png">
<link rel="preload" href="assets/fonts/cormorant-garamond.woff2" as="font" type="font/woff2" crossorigin>
<link rel="preload" href="assets/fonts/jost.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="assets/css/styles.css?v=${assetVersion}">
<script src="assets/js/store-data.js?v=${assetVersion}" defer></script>
<script src="assets/js/site.js?v=${assetVersion}" defer></script>
</head>`;
}

function navLink(page, item) {
  return html`<a href="${item.href}"${page.id === item.id ? html` aria-current="page"` : ''}>${item.label}</a>`;
}

/**
 * The header: the name on the left, the collections in the middle, customer
 * care and the bag on the right. On the home page it lies over the hero
 * photograph (see ".is-home .site-header" in styles.css).
 */
function header(page, { site, shopNav }) {
  const links = [...shopNav.filter((item) => item.inHeader), { id: 'about', href: 'about.html', label: 'Our Story' }];
  return html`<header class="site-header">
  <div class="site-header__inner">
    <button class="icon-btn site-header__menu" type="button" data-open="menu" aria-label="Open menu">${icon('menu')}</button>
    <a class="wordmark" href="index.html" aria-label="${site.name} home">${site.name}</a>
    <nav class="site-nav" aria-label="Main">
      <ul>
        ${links.map((item) => html`<li>${navLink(page, item)}</li>`)}
      </ul>
    </nav>
    <div class="site-header__actions">
      <a class="site-header__link" href="account.html"${page.id === 'account' ? html` aria-current="page"` : ''}>Account</a>
      <a class="site-header__link" href="help.html"${page.id === 'help' ? html` aria-current="page"` : ''}>Customer care</a>
      <button class="bag-btn" type="button" data-open="bag" data-bag-button data-count="0" aria-label="Open bag">
        ${icon('bag', { size: 20 })}
        <span class="bag-btn__text">Bag</span>
        <span class="bag-btn__count" data-bag-count>0</span>
      </button>
    </div>
  </div>
</header>`;
}

/** Contact links for the footer and help page. Only details that are set appear. */
export function contactLinks(site) {
  const { contact } = site;
  const links = [];
  if (contact.whatsapp) links.push({ icon: 'chat', label: 'WhatsApp', href: whatsappUrl(site), external: true });
  if (contact.phone) links.push({ icon: 'phone', label: contact.phone, href: `tel:${contact.phone.replace(/[^\d+]/g, '')}` });
  if (contact.email) links.push({ icon: 'mail', label: contact.email, href: `mailto:${contact.email}` });
  if (contact.instagram) links.push({ icon: 'instagram', label: 'Instagram', href: contact.instagram, external: true });
  if (contact.facebook) links.push({ icon: 'facebook', label: 'Facebook', href: contact.facebook, external: true });
  return links;
}

export function contactList(site, className = 'contact-list') {
  const links = contactLinks(site);
  if (links.length === 0) return '';
  return html`<ul class="${className}">
    ${links.map(
      (link) => html`<li><a href="${link.href}"${link.external ? html` target="_blank" rel="noopener"` : ''}>${icon(link.icon, { size: 20 })}<span>${link.label}</span></a></li>`,
    )}
  </ul>`;
}

/** Contact links as icons alone, for the footer. Only details that are set appear. */
function contactIcons(site) {
  const links = contactLinks(site);
  if (links.length === 0) return '';
  return html`<ul class="site-footer__contact">
    ${links.map(
      (link) => html`<li><a href="${link.href}" aria-label="${link.label}"${link.external ? html` target="_blank" rel="noopener"` : ''}>${icon(link.icon, { size: 20 })}</a></li>`,
    )}
  </ul>`;
}

const FOOTER_LINKS = [
  { id: 'shop', href: 'shop.html', label: 'Shop' },
  { id: 'about', href: 'about.html', label: 'Our Story' },
  { id: 'help', href: 'help.html', label: 'Customer care' },
  { href: 'help.html#size-guide', label: 'Size guide' },
  { href: 'help.html#contact', label: 'Contact' },
];

const POLICY_LINKS = [
  { href: 'help.html#delivery', label: 'Delivery' },
  { href: 'help.html#payment', label: 'Payment' },
  { href: 'help.html#exchanges', label: 'Exchanges' },
  { href: 'help.html#care', label: 'Garment care' },
  { href: 'account.html', label: 'Your account' },
];

function footer(page, { site, year }) {
  return html`<footer class="site-footer" id="footer">
  <div class="container">
    <div class="site-footer__main">
      <div class="site-footer__brand">
        <a class="wordmark wordmark--lg" href="index.html" aria-label="${site.name} home">${site.name}</a>
        <p>${site.tagline}</p>
      </div>
      <nav class="site-footer__nav" aria-label="Footer">
        <ul>
          ${FOOTER_LINKS.map((item) => html`<li>${navLink(page, item)}</li>`)}
        </ul>
      </nav>
      ${contactIcons(site)}
    </div>
    <div class="site-footer__base">
      <p>&copy; ${year} ${site.name}. All rights reserved.</p>
      <ul>
        ${POLICY_LINKS.map((item) => html`<li><a href="${item.href}">${item.label}</a></li>`)}
      </ul>
    </div>
  </div>
</footer>`;
}

function menuDialog(page, { site, shopNav }) {
  const secondary = [
    { id: 'about', href: 'about.html', label: 'Our Story' },
    { id: 'help', href: 'help.html', label: 'Customer care' },
    { id: 'account', href: 'account.html', label: 'Your account' },
  ];
  return html`<dialog class="drawer drawer--start" id="menu" aria-label="Menu">
  <div class="drawer__head">
    <span class="wordmark">${site.name}</span>
    <button class="icon-btn" type="button" data-close aria-label="Close menu">${icon('close')}</button>
  </div>
  <nav class="drawer__body menu" aria-label="Main">
    <ul class="menu__primary">
      ${shopNav.map((item) => html`<li>${navLink(page, item)}</li>`)}
    </ul>
    <ul class="menu__secondary">
      ${secondary.map((item) => html`<li>${navLink(page, item)}</li>`)}
    </ul>
  </nav>
</dialog>`;
}

/**
 * The shopping bag drawer, plus the template each bag line is stamped from.
 * assets/js/site.js fills these in; the same line template is reused by the
 * order summary on the checkout page.
 */
function bagDialog({ site }) {
  return html`<dialog class="drawer drawer--end" id="bag" aria-labelledby="bag-title">
  <div class="drawer__head">
    <h2 class="drawer__title" id="bag-title">Your bag</h2>
    <button class="icon-btn" type="button" data-close aria-label="Close bag">${icon('close')}</button>
  </div>
  <div class="drawer__body">
    <div class="bag-empty" data-bag-empty>
      <p>Your bag is empty.</p>
      <a class="btn btn--ghost" href="shop.html">Shop all pieces</a>
    </div>
    <ul class="bag-lines" data-bag-lines></ul>
  </div>
  <div class="drawer__foot" data-bag-filled hidden>
    <div class="bag-progress" data-bag-progress>
      <p data-bag-progress-text></p>
      <div class="bag-progress__track" aria-hidden="true"><span data-bag-progress-bar></span></div>
    </div>
    <dl class="totals">
      <div><dt>Subtotal</dt><dd data-bag-subtotal></dd></div>
    </dl>
    <a class="btn btn--primary btn--block" href="checkout.html">Checkout</a>
    <p class="drawer__note">Cash on delivery. Delivery in ${site.delivery.time}.</p>
  </div>
</dialog>
<template id="bag-line">
  <li class="bag-line">
    <a class="bag-line__media" data-line-link tabindex="-1" aria-hidden="true"><img data-line-image alt="" width="72" height="90" loading="lazy" decoding="async"></a>
    <div class="bag-line__info">
      <a class="bag-line__name" data-line-link data-line-name></a>
      <p class="bag-line__meta" data-line-title></p>
      <p class="bag-line__meta" data-line-size></p>
      <div class="stepper" role="group" data-line-stepper>
        <button type="button" data-line-decrease aria-label="Decrease quantity">${icon('minus', { size: 16 })}</button>
        <span class="stepper__value" data-line-quantity></span>
        <button type="button" data-line-increase aria-label="Increase quantity">${icon('plus', { size: 16 })}</button>
      </div>
    </div>
    <div class="bag-line__side">
      <p class="bag-line__price" data-line-total></p>
      <button class="link-btn" type="button" data-line-remove>Remove</button>
    </div>
  </li>
</template>`;
}

/** Wraps a page's content in the full document: head, header, footer and dialogs. */
export function layout(page, context) {
  return html`<!doctype html>
<!-- ${GENERATED_MARKER} from the files in src/. Do not edit by hand. -->
<html lang="en">
${head(page, context)}
<body${page.bodyClass ? html` class="${page.bodyClass}"` : ''}>
<a class="skip-link" href="#main">Skip to content</a>
${header(page, context)}
<main id="main">
${page.body}
</main>
${footer(page, context)}
${menuDialog(page, context)}
${bagDialog(context)}
${page.dialogs ?? ''}
<div class="visually-hidden" aria-live="polite" data-live></div>
</body>
</html>
`.toString();
}
